-- Disposable SQL/Auth-stub acceptance only. All synthetic fixture rows roll back.
begin;
create function pg_temp.ov_ok(v boolean,label text) returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Observed verification assertion: %',label;end if;end$$;
create function pg_temp.ov_denied(q text,expected text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=expected then return;end if;raise exception 'Expected % got %',expected,sqlstate;end;raise exception 'Expected refusal %',expected;end$$;
do $$begin execute format('grant usage on schema %I to anon,authenticated,service_role',pg_my_temp_schema()::regnamespace::text);end$$;
select pg_temp.ov_ok(not has_function_privilege(r,'public.pipstart_publication_verify_observed(bigint,text,text,integer)','execute'),'API denial '||r) from unnest(array['anon','authenticated','pipstart_publication_scheduler'])r;
select pg_temp.ov_ok(has_function_privilege('service_role','public.pipstart_publication_verify_observed(bigint,text,text,integer)','execute'),'service API grant');
